"""ME-REVISE-4: float placement (review 4, presentation). The sensitivity sheet (tables/rev_spec.tex, generated by
revision/analyze_rev.py, a [t] table* about 0.6 of the text height) was never placed at the top of a text page: with placeins'
section barrier it came out on a float page of its own after Section 4.5's last lines, leaving the page before mostly blank
(v4 page 20: text covers 0.07 of the page; v5's first build page 21: 0.19; revision4/page_fill.py). Moving its input to the
start of the subsection did not change that (second build), so a derived copy with the [p] placement,
tables/rev_spec_p.tex, is input instead: it goes to the first float page available and the text runs on. The generated
tables/rev_spec.tex is left as it is (its generator is not changed).

    python -B revision4/edit_tex_4b.py   (run once, after edit_tex_4.py)
"""
from pathlib import Path

T = Path(__file__).resolve().parent.parent / "tex"
src = (T / "tables" / "rev_spec.tex").read_bytes().decode("utf-8")
a = "\\begin{table*}[t]"
assert src.count(a) == 1
(T / "tables" / "rev_spec_p.tex").write_bytes(
    ("% derived by revision4/edit_tex_4b.py from tables/rev_spec.tex: placement [p] instead of [t]\n" + src.replace(a, "\\begin{table*}[p]")).encode("utf-8"))
p = T / "sec_spec.tex"
t = p.read_bytes().decode("utf-8")
head = "\\subsection{Sensitivity against absolute lines}\\label{sec:spec}\n"
inp = "\\input{tables/rev_spec.tex}\n"
assert t.count(inp) == 1 and t.startswith(head)
# defined at the start of the subsection (it was input after the subsection's last paragraph, so it could not be placed
# before that text) and placed [p]
p.write_bytes((head + "\\input{tables/rev_spec_p.tex}\n" + t[len(head):].replace(inp, "")).encode("utf-8"))
print("sec_spec.tex now inputs tables/rev_spec_p.tex ([p]) at its start")
